sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float radius;
uniform float softness;
uniform float roundness;

half4 main(float2 coord) {
    float2 norm = (coord / size - 0.5) * 2.0;
    float dx = norm.x, dy = norm.y;
    float d_sq = dx*dx + dy*dy;
    float circleDist = sqrt(d_sq);
    float rectDist = max(abs(dx), abs(dy));
    float dist = mix(rectDist, circleDist, roundness);
    float edge = radius;
    float t = smoothstep(edge - softness, edge + softness, dist);
    float vignette = 1.0 - (amount * clamp(t, 0, 1));
    half4 color = image.eval(coord);
    half a = color.a;
    if (a > 0.0001) {
        color.rgb /= a;
        color.rgb *= vignette;
        color.rgb *= a;
    } else {
        color = half4(0);
    }
    return color;
}
